using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Globalization;
using System.Windows.Forms;

sealed partial class SoundCanvas {
 public bool HasBackground {get{return backgroundImage!=null;}}
 public bool Recording;public Action<double,double> CaptureSample,PickOrigin;
 public List<TraceShape> Traces=new List<TraceShape>();Image backgroundImage;
 public void SetBackground(Image image){if(backgroundImage!=null)backgroundImage.Dispose();backgroundImage=new Bitmap(image);Invalidate();}
 public void ClearBackground(){if(backgroundImage!=null){backgroundImage.Dispose();backgroundImage=null;}ImageCrop=new RectangleF(0,0,1,1);if(ImageCleared!=null)ImageCleared();Invalidate();}
 void PaintBackgroundImage(Graphics g,RectangleF view){if(backgroundImage==null||HideDrawing)return;float baseScale=Math.Min(568f/backgroundImage.Width,418f/backgroundImage.Height);float w=backgroundImage.Width*baseScale*ImageCrop.Width,h=backgroundImage.Height*baseScale*ImageCrop.Height;float zoom=Math.Min(568f/w,418f/h);w*=zoom;h*=zoom;g.DrawImage(backgroundImage,new RectangleF(view.X+(600-w)*view.Width/1200,view.Y+(450-h)*view.Height/900,w*view.Width/600,h*view.Height/450),new RectangleF(ImageCrop.X*backgroundImage.Width,ImageCrop.Y*backgroundImage.Height,ImageCrop.Width*backgroundImage.Width,ImageCrop.Height*backgroundImage.Height),GraphicsUnit.Pixel);}
 void PaintTraces(Graphics g,RectangleF view){if(HideDrawing)return;using(Pen p=new Pen(Color.Cyan,3)){foreach(TraceShape s in Traces){PointF[] points=Array.ConvertAll(s.Points,q=>new PointF(view.X+q.X*view.Width/600,view.Y+q.Y*view.Height/450));if(points.Length==1)g.DrawEllipse(p,points[0].X-3,points[0].Y-3,6,6);else if(points.Length>1){g.DrawLines(p,points);if(s.Closed)g.DrawLine(p,points[points.Length-1],points[0]);}}}}
}

sealed partial class FormasForm {
 void BuildPlayback(){var p=Page("Orientación y pausa");
  Paragraph(p,"Consulta la vista general o tu posición. Pausar conserva el recorrido; Detener, tocar el lienzo y cambiar la escena lo cancelan. Retroceder y volver al marcador dejan el audio en pausa: pulsa Continuar cuando estés listo.");
  Button(p,"Vista general de la capa actual",()=>Send("OVERVIEW"));
  Button(p,"Dónde dejé el puntero",()=>Send("WHERE|"+canvas.Position.X.ToString(CultureInfo.InvariantCulture)+"|"+canvas.Position.Y.ToString(CultureInfo.InvariantCulture)));
  string[] labels={"Pausar recorrido","Continuar recorrido","Retroceder cinco segundos y pausar","Guardar marcador y pausar","Volver al marcador","Repetir últimos cinco segundos","Dónde estoy en el recorrido"};
  string[] commands={"pause","resume","back","mark","return","fragment","position"};
  for(int i=0;i<labels.Length;i++){string command=commands[i];Button(p,labels[i],()=>{if(voice!=null)voice.SpeakAsyncCancelAll();Send("CONTROL|"+command);Log("playback_"+command);});}
  Paragraph(p,"Repetir reproduce los últimos cinco segundos y pausa en el punto original. Al inicio reproduce los primeros cinco segundos. El marcador pertenece al recorrido actual. Los perfiles cambian el timbre y conservan las reglas de posición.");
 }
 readonly object drawingCacheGate=new object();
 readonly CheckBox recordTrace=new CheckBox(),invertScan=new CheckBox(),heightDeclared=new CheckBox();
 readonly ComboBox traceSelection=new ComboBox(),layerSelection=new ComboBox(),scanMode=new ComboBox(),scanOrigin=new ComboBox();
 readonly NumericUpDown scanStep=new NumericUpDown(),scanCenter=new NumericUpDown(),scanWindow=new NumericUpDown();
 readonly TextBox traceLabel=new TextBox();bool captureOpen;int fragment=-1,scanSection=-1;PointF scanStart=new PointF(0,0);long captureEpoch=-1;
 readonly NumericUpDown coordinateX=new NumericUpDown(),coordinateY=new NumericUpDown();
 void AddCoordinate(bool first){recordTrace.Checked=false;EndCapture();Stop();Send("DRAW_POINT|"+coordinateX.Value+"|"+coordinateY.Value+"|"+first.ToString().ToLowerInvariant()+"|"+B64(traceLabel.Text));layerSelection.SelectedIndex=1;Log(first?"coordinate_start":"coordinate_extend");}
 void BuildStudio(){var p=Page("Trazar y leer");Number(p,coordinateX,"Coordenada horizontal: 0 izquierda, 600 derecha",0,600,300,()=>{});Number(p,coordinateY,"Coordenada vertical: 0 arriba, 450 abajo",0,450,225,()=>{});Button(p,"Crear trazo con este punto inicial",()=>AddCoordinate(true));Button(p,"Añadir punto al último trazo",()=>AddCoordinate(false));Paragraph(p,"Dibujo por coordenadas: cada punto añadido se une al anterior; usa la etiqueta antes de crear el trazo. Los tiempos de estos puntos son sintéticos, de un segundo. Deshacer elimina el trazo completo.");Paragraph(p,"Una persona puede dibujar o remarcar mientras otra escucha, en esta misma computadora. Desactiva Dibujar para explorar lo registrado. Los trazos conservan orden y tiempos; el fondo no se incluye al guardar el proyecto.");
  Paragraph(p,"Etiqueta para el siguiente trazo; es una anotación del acompañante");traceLabel.Width=650;traceLabel.MaxLength=120;traceLabel.AccessibleName="Etiqueta del siguiente trazo";p.Controls.Add(traceLabel);
  Check(p,recordTrace,"Dibujar o remarcar con sonido en directo",false,()=>{EndCapture();canvas.Recording=recordTrace.Checked;if(recordTrace.Checked){layerSelection.SelectedIndex=1;canvas.Focus();Say("Dibujo activo. Mantén el botón izquierdo o desliza un dedo. Levantar termina el trazo. Escape detiene y desactiva dibujo.");}});
  Select(p,"Capa que responde al explorar",layerSelection,new string[]{"Sólo fondo","Sólo trazos","Fondo y trazos","Sólo trazo seleccionado"},0,()=>{Stop();Send("LAYER|"+layerSelection.SelectedIndex);});
  Button(p,"Explorar los trazos sin dibujar",()=>{recordTrace.Checked=false;layerSelection.SelectedIndex=1;canvas.Focus();});Select(p,"Trazo para repetir",traceSelection,new string[0],0,()=>{fragment=-1;Send("SELECT_TRACE|"+traceSelection.SelectedIndex);});
  Button(p,"Reproducir todos los trazos en orden",()=>PlayDrawing(-1,-1));Button(p,"Escuchar trazo seleccionado",()=>PlayDrawing(traceSelection.SelectedIndex,-1));Button(p,"Escuchar siguiente fragmento de hasta 20 segmentos",()=>{fragment++;PlayDrawing(traceSelection.SelectedIndex,fragment);});Button(p,"Volver al primer fragmento",()=>{fragment=0;PlayDrawing(traceSelection.SelectedIndex,fragment);});
  Button(p,"Cerrar último trazo como región",()=>{EndCapture();if(canvas.Traces.Count==0||canvas.Traces[canvas.Traces.Count-1].Points.Length<3){Say("Necesitas al menos tres puntos para cerrar una región.");return;}Send("DRAW_CLOSE|true");Log("trace_close");});Button(p,"Deshacer último trazo",()=>{EndCapture();Send("DRAW_UNDO");Log("trace_undo");});Button(p,"Borrar todos los trazos",()=>{if(MessageBox.Show(this,"¿Borrar todos los trazos de este proyecto? El fondo se conserva.","Borrar trazos",MessageBoxButtons.YesNo)==DialogResult.Yes){EndCapture();Send("DRAW_CLEAR");}});
  Button(p,"Ejemplo de cara esquemática",()=>DrawingDemo(0));Button(p,"Ejemplo de ruta con giros",()=>DrawingDemo(1));Button(p,"Ejemplo de gesto cursivo",()=>DrawingDemo(2));
  Button(p,"Guardar proyecto de trazos",()=>{EndCapture();Send("DRAW_EXPORT|export");});Button(p,"Abrir proyecto de trazos",OpenDrawing);
  Paragraph(p,"Lectura secuencial: luminosidad sonora por filas, columnas o cuadrantes; relleno respeta la silueta extraída. La selección de inicio conserva la posición de la imagen. El contorno empieza en el vértice muestreado más cercano al inicio elegido.");
  Select(p,"Recorrido de lectura",scanMode,new string[]{"Filas","Columnas","Cuadrantes","Relleno de la silueta","Contorno desde referencia"},0,()=>scanSection=-1);
  Select(p,"Punto de partida",scanOrigin,new string[]{"Superior izquierda","Superior derecha","Inferior derecha","Inferior izquierda","Posición marcada"},0,()=>scanSection=-1);
  Button(p,"Usar posición actual del lienzo como inicio",()=>{scanStart=canvas.Position;scanOrigin.SelectedIndex=4;Say("Inicio marcado sin desplazar la imagen.");});Button(p,"Marcar inicio con el próximo toque o clic",()=>{recordTrace.Checked=false;canvas.PickOrigin=(x,y)=>{scanStart=new PointF((float)x,(float)y);scanOrigin.SelectedIndex=4;Say("Inicio marcado.");};canvas.Focus();});
  Number(p,scanStep,"Separación del barrido, unidades",16,80,40,()=>scanSection=-1);Number(p,scanCenter,"Centro de luminosidad, 0 a 255",0,255,128,()=>{});Number(p,scanWindow,"Amplitud de contraste, 1 a 255",1,255,255,()=>{});Check(p,invertScan,"Invertir luminosidad o altura declarada",false,()=>{});
  Button(p,"Leer recorrido completo",()=>ReadScan(-1));Button(p,"Leer siguiente fila o cuadrante",()=>{scanSection++;ReadScan(scanSection);});Button(p,"Volver a primera sección",()=>{scanSection=0;ReadScan(scanSection);});
  Check(p,heightDeclared,"Interpretar imagen importada como mapa de alturas aportado",false,()=>{Stop();if(heightDeclared.Checked&&!canvas.HasBackground){heightDeclared.Checked=false;Say("Importa primero el mapa de alturas como imagen de fondo.");return;}Send("HEIGHT|"+heightDeclared.Checked.ToString().ToLowerInvariant());Say("Sólo actívalo con un mapa de alturas conocido. Blanco representa mayor altura relativa mediante más intensidad; no son milímetros ni profundidad inferida de una foto.");});
  Paragraph(p,"Caras: usa el ejemplo o marca manualmente rasgos sobre una foto. No hay identificación ni detección facial automática. Radiografías: sólo imágenes PNG/JPEG de estudio y marcas del docente; no abre DICOM ni valida hallazgos clínicos. El blanco de una radiografía no es relieve físico.");
 }
 int StudioPointCount(){int count=0;foreach(TraceShape trace in canvas.Traces)count+=trace.Points.Length;return count;}
 void CaptureSample(double x,double y){if(!ready)return;long now=elapsed.ElapsedMilliseconds;if(captureEpoch<0)captureEpoch=now;long time=now-captureEpoch;string xy=x.ToString(CultureInfo.InvariantCulture)+"|"+y.ToString(CultureInfo.InvariantCulture)+"|"+time;
  if(!captureOpen){captureOpen=true;Send("DRAW_BEGIN|"+xy+"|"+B64(traceLabel.Text));canvas.Traces.Add(new TraceShape{Points=new PointF[]{new PointF((float)x,(float)y)}});Log("trace_begin");}
  else{Send("DRAW_MOVE|"+xy);if(canvas.Traces.Count>0){TraceShape last=canvas.Traces[canvas.Traces.Count-1];var pts=new List<PointF>(last.Points);if(pts.Count<20000)pts.Add(new PointF((float)x,(float)y));last.Points=pts.ToArray();}}canvas.Invalidate();
 }
 void EndCapture(){if(!captureOpen)return;captureOpen=false;Send("DRAW_END|"+(elapsed.ElapsedMilliseconds-captureEpoch));Log("trace_end");}
 void ReceiveTraces(string[] a){canvas.Traces=ParseShapes(a[2]);string[] labels=Decode(a[1]).Split(new char[]{'\n'},StringSplitOptions.None);bool old=loading;loading=true;int selected=traceSelection.SelectedIndex;traceSelection.Items.Clear();for(int i=0;i<canvas.Traces.Count;i++)traceSelection.Items.Add((i+1)+". "+(i<labels.Length&&labels[i].Length>0?labels[i]:"Trazo sin etiqueta"));if(traceSelection.Items.Count>0)traceSelection.SelectedIndex=Math.Min(Math.Max(0,selected),traceSelection.Items.Count-1);loading=old;Send("SELECT_TRACE|"+traceSelection.SelectedIndex);Send("DRAW_EXPORT|cache");canvas.Invalidate();Say(canvas.Traces.Count+" trazos; "+a[3]+" puntos. Puedes repetirlos o explorarlos.");}
 void PlayDrawing(int selected,int part){recordTrace.Checked=false;EndCapture();Stop();if(selected<0&&traceSelection.Items.Count==0){Say("Todavía no hay trazos.");return;}Send("DRAW_PLAY|"+selected+"|"+part);Log("trace_play");}
 void DrawingDemo(int n){if(!smoke&&canvas.Traces.Count>0&&MessageBox.Show(this,"El ejemplo reemplaza los trazos actuales. Guarda el proyecto si quieres conservarlos. ¿Continuar?","Cargar ejemplo",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;recordTrace.Checked=false;Stop();Send("DRAW_DEMO|"+n);layerSelection.SelectedIndex=1;captureEpoch=-1;Log("trace_demo_"+n);}
 void ReadScan(int section){recordTrace.Checked=false;EndCapture();Stop();PointF origin=scanOrigin.SelectedIndex==4?scanStart:new PointF(scanOrigin.SelectedIndex==1||scanOrigin.SelectedIndex==2?600:0,scanOrigin.SelectedIndex>=2?450:0);Send("SCAN|"+scanMode.SelectedIndex+"|"+origin.X.ToString(CultureInfo.InvariantCulture)+"|"+origin.Y.ToString(CultureInfo.InvariantCulture)+"|"+scanStep.Value+"|"+section+"|"+scanCenter.Value+"|"+scanWindow.Value+"|"+invertScan.Checked.ToString().ToLowerInvariant());Log("scan_read");}
 void SaveDrawing(string payload,string action){string contents=json.Serialize(new Dictionary<string,object>{{"schema","formas-trace-v1"},{"payload",payload}});PersistDrawing(payload);if(action!="export")return;using(var dialog=new SaveFileDialog()){dialog.Filter="Proyecto de trazos|*.formas.json";dialog.FileName="trazos.formas.json";if(dialog.ShowDialog(this)==DialogResult.OK)try{File.WriteAllText(dialog.FileName,contents,System.Text.Encoding.UTF8);Say("Proyecto guardado. Contiene trazos, etiquetas y tiempos; no contiene la foto de fondo.");}catch(Exception e){Say("No se pudo guardar: "+e.Message);}}}
 void PersistDrawing(string payload){try{lock(drawingCacheGate){string target=Path.Combine(storage,"studio-current.json"),temp=target+".tmp";File.WriteAllText(temp,"{\"schema\":\"formas-trace-v1\",\"payload\":\""+payload+"\"}",System.Text.Encoding.UTF8);if(File.Exists(target))File.Replace(temp,target,null);else File.Move(temp,target);}}catch{if(!closing)try{BeginInvoke((Action)(()=>Say("No se pudo conservar el proyecto local; usa Guardar proyecto.")));}catch{}}}
 void LoadStoredDrawing(){try{string path=Path.Combine(storage,"studio-current.json");if(File.Exists(path)&&new FileInfo(path).Length<2000000){var value=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(path));if((string)value["schema"]=="formas-trace-v1")Send("DRAW_IMPORT|"+(string)value["payload"]);}}catch{Say("No se pudo recuperar el último proyecto. Puedes abrir una copia guardada.");}}
 void OpenDrawing(){if(canvas.Traces.Count>0&&MessageBox.Show(this,"Abrir otro proyecto reemplaza los trazos actuales. Guarda una copia si quieres conservarlos. ¿Continuar?","Abrir proyecto",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;recordTrace.Checked=false;using(var dialog=new OpenFileDialog()){dialog.Filter="Proyecto de trazos|*.formas.json;*.json";if(dialog.ShowDialog(this)!=DialogResult.OK)return;try{if(new FileInfo(dialog.FileName).Length>2000000)throw new InvalidDataException("Proyecto mayor de 2 MB");var data=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(dialog.FileName));if(!data.ContainsKey("schema")||(string)data["schema"]!="formas-trace-v1")throw new InvalidDataException("Formato incompatible");Send("DRAW_IMPORT|"+(string)data["payload"]);layerSelection.SelectedIndex=1;captureEpoch=-1;Log("trace_import");}catch(Exception e){Say("No se pudo abrir: "+e.Message);}}}
}
